export function calculateUserScore(user: any) {
  const base = user.orders.length * 10;
  const bonus = user.reviews.length * 2;
  return base + bonus;
}

export function calculateAdminScore(admin: any) {
  const base = admin.orders.length * 10;
  const bonus = admin.reviews.length * 2;
  return base + bonus;
}

export function validateOrderV1(order: any) {
  if (!order.id) throw new Error('missing id');
  if (order.items.length === 0) throw new Error('no items');
  if (!order.customerEmail.includes('@')) throw new Error('bad email');
}

export function validateOrderV2(order: any) {
  if (!order.id) throw new Error('missing id');
  if (order.items.length === 0) throw new Error('no items');
  if (!order.email || !order.email.includes('@')) throw new Error('bad email');
}

// Version A: small shared helper reused across modules
export function calcDiscountA(price: number, tier: string) {
  if (tier === 'GOLD') return price * 0.8;
  if (tier === 'SILVER') return price * 0.9;
  return price;
}

// Version B: focused domain service encapsulating discount behavior
export class DiscountService {
  apply(price: number, tier: string) {
    if (tier === 'GOLD') return price * 0.8;
    if (tier === 'SILVER') return price * 0.9;
    return price;
  }
}
